begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('10000000-0000-4000-8000-000000000003','domains-owner@example.invalid'),('10000000-0000-4000-8000-000000000004','domains-other@example.invalid');
delete from private.app_owner;
insert into private.app_owner(user_id,github_user_id) values('10000000-0000-4000-8000-000000000003','10003');
select ok(not has_table_privilege('anon','public.notes','SELECT'),'anon Notes read closed');
select ok(not has_table_privilege('anon','public.calendar_events','INSERT'),'anon Calendar write closed');
select ok(not has_function_privilege('anon','public.create_today(uuid,date,text,text)','EXECUTE'),'anon Today RPC closed');
select ok(not has_column_privilege('authenticated','public.today_items','item_date','UPDATE'),'direct Today move denied');
select ok(not has_table_privilege('authenticated','public.today_items','INSERT'),'direct Today create denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select lives_ok($$insert into public.notes(id,title) values('30000000-0000-4000-8000-000000000001','fixture')$$,'owner creates Notes');
select lives_ok($$update public.notes set title='updated' where id='30000000-0000-4000-8000-000000000001' and revision=1$$,'Notes update');
select is((select revision from public.notes where id='30000000-0000-4000-8000-000000000001'),2,'DB increments revision');
select throws_ok($$update public.notes set revision=9$$,'42501',null,'cannot set own revision');
select throws_ok($$insert into public.notes(id,title,color) values(gen_random_uuid(),'bad','bad')$$,'23514',null,'Notes color constraint');
select throws_ok($$insert into public.notes(id,title,content) values(gen_random_uuid(),'bad','[]')$$,'23514',null,'Notes shape constraint');
select lives_ok($$select public.create_today('30000000-0000-4000-8000-000000000002','2098-01-01','one','work')$$,'Today create slot one');
select lives_ok($$select public.create_today('30000000-0000-4000-8000-000000000003','2098-01-01','two','personal')$$,'Today create slot two');
select lives_ok($$select public.create_today('30000000-0000-4000-8000-000000000004','2098-01-01','three','learning')$$,'Today create slot three');
update public.today_items set done=true where id='30000000-0000-4000-8000-000000000002';
select throws_ok($$select public.create_today(gen_random_uuid(),'2098-01-01','four','work')$$,'P0001','full','completed occupies capacity');
select lives_ok($$select public.create_today('30000000-0000-4000-8000-000000000005','2098-01-02','source','work')$$,'Today source create');
select throws_ok($$select public.move_today('30000000-0000-4000-8000-000000000005','2098-01-01',1)$$,'P0001','full','failed move');
select is((select item_date::text from public.today_items where id='30000000-0000-4000-8000-000000000005'),'2098-01-02','source retained');
select throws_ok($$select public.move_today('30000000-0000-4000-8000-000000000005','2098-01-03',null)$$,'22023','invalid revision','RPC null revision denied');
select lives_ok($$select public.move_today('30000000-0000-4000-8000-000000000005','2098-01-03',1)$$,'move commits');
select throws_ok($$select public.move_today('30000000-0000-4000-8000-000000000005','2098-01-04',1)$$,'P0001','conflict','stale move denied');
select lives_ok($$insert into public.calendar_events(id,title,color,category,kind,status,priority,starts_at,ends_at) values('30000000-0000-4000-8000-000000000006','event','blue','work','event','planned','medium','2098-01-01T23:30+07','2098-01-02T00:30+07')$$,'Calendar timed event');
select throws_ok($$insert into public.calendar_events(id,title,color,category,kind,status,priority,starts_on,ends_on) values(gen_random_uuid(),'event','blue','work','event','planned','medium','2098-01-01','2098-01-01')$$,'23514',null,'all-day end must follow start');
select lives_ok($$insert into public.calendar_settings(id) values(auth.uid())$$,'owner default settings');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
select is((select count(*)::int from public.notes),0,'non-owner Notes invisible');
select is((select count(*)::int from public.today_items),0,'non-owner Today invisible');
select is((select count(*)::int from public.calendar_events),0,'non-owner Calendar invisible');
select is((select count(*)::int from public.calendar_settings),0,'non-owner settings invisible');
select throws_ok($$insert into public.notes(id,title) values(gen_random_uuid(),'bad')$$,'42501',null,'non-owner Notes insert denied');
select throws_ok($$insert into public.calendar_events(id,title,color,category,kind,status,priority,starts_on,ends_on) values(gen_random_uuid(),'bad','blue','work','event','planned','medium','2098-01-01','2098-01-02')$$,'42501',null,'non-owner Calendar insert denied');
select throws_ok($$insert into public.calendar_settings(id) values(auth.uid())$$,'42501',null,'non-owner settings insert denied');
select throws_ok($$select public.create_today(gen_random_uuid(),'2098-01-01','bad','work')$$,'42501',null,'non-owner Today RPC denied');
select throws_ok($$select public.move_today('30000000-0000-4000-8000-000000000005','2098-01-04',2)$$,'42501',null,'non-owner move RPC denied');
reset role;
update private.app_owner set enabled=false;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*)::int from public.notes),0,'disabled Notes invisible');
select is((select count(*)::int from public.today_items),0,'disabled Today invisible');
select is((select count(*)::int from public.calendar_events),0,'disabled Calendar invisible');
select is((select count(*)::int from public.calendar_settings),0,'disabled settings invisible');
reset role;
select * from finish();
rollback;
